--
-- Disparadores `ventas`
--
DELIMITER $$
CREATE TRIGGER `trgActualizarStock` AFTER INSERT ON `ventas` FOR EACH ROW BEGIN
    UPDATE Productos
    SET Stock = Stock - NEW.Cantidad
    WHERE ProductoID = NEW.ProductoID;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_AfterInsertVentas` BEFORE INSERT ON `ventas` FOR EACH ROW BEGIN
    DECLARE precio DECIMAL(10,2);
    SELECT Precio_Venta INTO precio FROM Productos WHERE ProductoID = NEW.ProductoID;
    SET NEW.MontoTotal = NEW.Cantidad * precio;
END
$$
DELIMITER ;

